package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net/http"
)

func main() {
	body, _ := json.Marshal(map[string]string{"url": "https://example.com/", "country": "us"})
	req, _ := http.NewRequest("POST", "https://app.quanticdata.io/api/v1/scraper/unlock", bytes.NewReader(body))
	req.Header.Set("Authorization", "Bearer qd_live_YOUR_API_KEY")
	req.Header.Set("Content-Type", "application/json")
	res, err := http.DefaultClient.Do(req)
	if err != nil {
		panic(err)
	}
	defer res.Body.Close()
	var out struct {
		Payload struct {
			Status    int    `json:"status"`
			Blocked   bool   `json:"blocked"`
			LatencyMs int    `json:"latency_ms"`
			Body      string `json:"body"`
		} `json:"payload"`
	}
	json.NewDecoder(res.Body).Decode(&out)
	fmt.Println(out.Payload.Status, out.Payload.Blocked, out.Payload.LatencyMs, len(out.Payload.Body))
}

